  Lemma fdw_dec : forall mz j0' j32 j48 (d : dtable) (S0 : Z) (bs : list Z) (jd : list byte)
      (x5 x6 x7 x12 x13 x14 x16 x17 x28 x29 x30 x31 : word),
    finv mz j0' j32 j48 ->
    (* [comment removed for export] *)
    fse_decompress_wksp (repeat 0 256) dcap src maxLog wks = decompress_usingDTable bs d dcap (negb (dt_fastMode d =? 0)) ->
    5 <= dt_tableLog d <= 12 -> zlen (dt_cells d) = 2^(dt_tableLog d) -> RF_huf_fdw_sm.cells_ok (dt_tableLog d) (dt_cells d) ->
    (dt_fastMode d = 0 \/ dt_fastMode d = 1) ->
    (* [comment removed for export] *)
    rw_cells asegs mz (W + 512) [C2 (Z_to_bv 64 (dt_tableLog d)); C2 (Z_to_bv 64 (dt_fastMode d))] ->
    bytes_at asegs mz (W + 512 + 4) (concat (map fse_cell_bytes (dt_cells d))) ->
    hblk8 LB W wks -> W mod 8 = 0 -> 512 + 4 + 4 * 2^(dt_tableLog d) <= wks ->
    (* [comment removed for export] *)
    bytes_at asegs mz S0 (map (Z_to_bv 8) bs) -> Forall (fun c => 0 <= c < 256) bs -> zlen bs <= 65536 -> 16 <= S0 ->
    bufH LB S0 (zlen bs) ->
    u8arr asegs mz DST jd -> zlen jd = dcap ->
    (DST + dcap <= S0 \/ S0 + zlen bs <= DST) -> (DST + dcap <= W \/ W + wks <= DST) -> (S0 + zlen bs <= W \/ W + wks <= S0) ->
    (* [comment removed for export] *)
