    zshadow mz ABIT_MASK 128 ->
    S0 + zlen bs = S + zlen src -> 0 <= S ->
    dres_ok (decompress_usingDTable bs d dcap (negb (dt_fastMode d =? 0))) ->
    evtF asegs RNG POST
      (MS (mkR (Z_to_bv 64 0x95f2c) (Z_to_bv 64 (SPAf SPV)) gp tp x5 x6 x7 (Z_to_bv 64 SPV) (Z_to_bv 64 (SPAf SPV))
