  Lemma fdw_rd_ok : forall mx j0' j32 j48 (rt : list Z) msv tl ncl (jd jwr : list byte)
      (x5 x6 x7 x11 x12 x13 x14 x15 x16 x17 x28 x29 x30 x31 : word),
    finv mx j0' j32 j48 ->
    read_ncount (repeat 0 256) 255 src = Ok (rt, msv, tl, ncl) ->
    u8arr asegs mx W (u16s (map (Z_to_bv 64) rt)) ->
    rw_cells asegs mx (FF + 48) [C4 (Z_to_bv 64 msv)] -> rw_cells asegs mx (FF + 32) [C4 (Z_to_bv 64 tl)] ->
    u8arr asegs mx (W + 512) jwr -> zlen jwr = wks - 512 ->
    u8arr asegs mx DST jd -> zlen jd = dcap ->
    bytes_at asegs mx S (map (Z_to_bv 8) src) -> Forall (fun c => 0 <= c < 256) src ->
    hblk8 LB W wks -> W mod 8 = 0 -> bufH LB S (zlen src) -> 16 <= S ->
    512 <= wks -> wks < 2^32 -> 0 <= maxLog <= 12 -> zlen src <= 65536 ->
    (DST + dcap <= S \/ S + zlen src <= DST) -> (DST + dcap <= W \/ W + wks <= DST) -> (S + zlen src <= W \/ W + wks <= S) ->
    evtF asegs RNG POST
      (MS (mkR (Z_to_bv 64 0x95eb8) (Z_to_bv 64 (SPAf SPV)) gp tp x5 x6 x7 (Z_to_bv 64 SPV) (Z_to_bv 64 (SPAf SPV))
               (Z_to_bv 64 ncl) x11 x12 x13 x14 x15 x16 x17 (Z_to_bv 64 FF) (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880))
               (Z_to_bv 64 dcap) (Z_to_bv 64 maxLog) (Z_to_bv 64 (zlen src)) (Z_to_bv 64 S) (Z_to_bv 64 W) (Z_to_bv 64 wks)
               (Z_to_bv 64 (FF + 48)) (Z_to_bv 64 (FF + 32)) x28 x29 x30 x31)
          FR (Z_to_bv 64 0x95eb8) fc None mx (seg_rom asegs)).
